#include <zephyr/kernel.h>
#include <zephyr/pm/pm.h>
#include <zephyr/pm/device.h>
#include <zephyr/pm/policy.h>
#include <zephyr/ztest.h>

static atomic_t suspend_to_idle_count;
static atomic_t suspend_to_ram_count;
static atomic_t suspend_to_disk_count;

static void suspend_to_idle_post_op(enum pm_state state, uint8_t substate_id)
{
	atomic_inc(&suspend_to_idle_count);
}

static void suspend_to_ram_post_op(enum pm_state state, uint8_t substate_id)
{
	atomic_inc(&suspend_to_ram_count);
}

static void suspend_to_disk_post_op(enum pm_state state, uint8_t substate_id)
{
	atomic_inc(&suspend_to_disk_count);
}

/* Define the power states */
static const struct pm_state_info states[] = {
	PM_STATE_INFO(PM_STATE_SUSPEND_TO_IDLE, PM_STATE_SUBSTATE_NONE, suspend_to_idle_post_op),
	PM_STATE_INFO(PM_STATE_SUSPEND_TO_RAM, PM_STATE_SUBSTATE_NONE, suspend_to_ram_post_op),
	PM_STATE_INFO(PM_STATE_SUSPEND_TO_DISK, PM_STATE_SUBSTATE_NONE, suspend_to_disk_post_op),
};

static int pm_test_dev_pm_action(const struct device *dev,
				 enum pm_device_action action)
{
	return 0;
}

PM_DEVICE_DEFINE(pm_test_dev, pm_test_dev_pm_action);
DEVICE_DEFINE(pm_test_dev, "pm_test_dev", NULL, NULL, NULL, NULL,
	      APPLICATION, 0, NULL);

static void test_power_states(void)
{
	(void)atomic_set(&suspend_to_idle_count, 0);
	(void)atomic_set(&suspend_to_ram_count, 0);
	(void)atomic_set(&suspend_to_disk_count, 0);

	pm_system_force_power_state(PM_STATE_SUSPEND_TO_IDLE);
	zassert_equal(atomic_get(&suspend_to_idle_count), 1);

	pm_system_force_power_state(PM_STATE_SUSPEND_TO_RAM);
	zassert_equal(atomic_get(&suspend_to_ram_count), 1);

	pm_system_force_power_state(PM_STATE_SUSPEND_TO_DISK);
	zassert_equal(atomic_get(&suspend_to_disk_count), 1);
}

static void test_device_power_state_constraints(void)
{
	const struct device *const dev = DEVICE_GET(pm_test_dev);
	struct pm_device_power_state_constraints constraints;

	/* By default all states are enabled */
	(void)atomic_set(&suspend_to_ram_count, 0);
	pm_system_force_power_state(PM_STATE_SUSPEND_TO_RAM);
	zassert_equal(atomic_get(&suspend_to_ram_count), 1,
		      "suspend_to_ram_count should be 1");

	/*
	 * Let's disable suspend to ram when device is in active state.
	 */
	(void)atomic_set(&suspend_to_ram_count, 0);
	constraints = (struct pm_device_power_state_constraints){
		.flags = PM_DEVICE_POWER_STATE_FLAG_ACTIVE,
	};
	/* By default, all states are allowed */
	memset(constraints.states, 1, sizeof(constraints.states));

	/*
	 * We are setting constraints for PM_DEVICE_STATE_ACTIVE, so we need
	 * to make sure the device is in this state.
	 */
	pm_device_state_set(dev, PM_DEVICE_STATE_ACTIVE);
	/* Disable suspend to ram */
	constraints.states[PM_STATE_SUSPEND_TO_RAM] = 0;
	pm_device_power_state_constraints_set(dev, &constraints);
	pm_system_force_power_state(PM_STATE_SUSPEND_TO_RAM);
	zassert_equal(atomic_get(&suspend_to_ram_count), 0,
		      "suspend_to_ram_count should be 0");

	/* Now, let's enable it back */
	constraints.states[PM_STATE_SUSPEND_TO_RAM] = 1;
	pm_device_power_state_constraints_set(dev, &constraints);
	pm_system_force_power_state(PM_STATE_SUSPEND_TO_RAM);
	zassert_equal(atomic_get(&suspend_to_ram_count), 1,
		      "suspend_to_ram_count should be 1");

	/* Finally, let's remove the constraint */
	(void)atomic_set(&suspend_to_ram_count, 0);
	pm_device_power_state_constraints_set(dev, NULL);
	pm_system_force_power_state(PM_STATE_SUSPEND_TO_RAM);
	zassert_equal(atomic_get(&suspend_to_ram_count), 1,
		      "suspend_to_ram_count should be 1");
}

static void *power_states_1cpu_setup(void)
{
	/*
	 * Let's make sure the device is in active state.
	 */
	pm_device_state_set(DEVICE_GET(pm_test_dev), PM_DEVICE_STATE_ACTIVE);

	return NULL;
}

static void power_states_1cpu_before(void *fixture)
{
	ARG_UNUSED(fixture);

	(void)atomic_set(&suspend_to_idle_count, 0);
	(void)atomic_set(&suspend_to_ram_count, 0);
	(void)atomic_set(&suspend_to_disk_count, 0);
}

unsigned int pm_policy_get_state_count(void)
{
	return ARRAY_SIZE(states);
}

const struct pm_state_info *pm_policy_get_states(void)
{
	return states;
}

ZTEST_SUITE(power_states_1cpu, NULL, power_states_1cpu_setup,
	    power_states_1cpu_before, NULL, NULL);

ZTEST(power_states_1cpu, test_power_states)
{
	test_power_states();
}

ZTEST(power_states_1cpu, test_device_power_state_constraints)
{
	test_device_power_state_constraints();
}
